  assertEquals("UnquotedSingleWord", gson.fromJson("UnquotedSingleWord", String.class));

  String value = "String Blah Blah Blah...1, 2, 3";
  try {
    gson.fromJson(value, String.class);
    fail();
  } catch (JsonSyntaxException expected) { }
}

